pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzzed params: from address and an arbitrary uint value; we will pass an empty array _tos to trigger the difference
    function testFuzz_property(address from, uint256 v) public {
        // keep from a non-zero address to be in admissible domain
        vm.assume(from != address(0));

        address[] memory tos = new address[](0);

        // call transfer and record whether it reverts or not
        bool ok;
        try c.transfer(from, address(this), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE: Reference C always REVERTS when _tos is empty, so ok must be false for all inputs.
        // The mutant removing the require will make ok==true for some inputs (e.g., many fuzzed values),
        // causing this assertion to fail on the buggy version.
        assertTrue(!ok);
    }
}
